"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3987],{4147(e){e.exports=JSON.parse('{"title":"React \ud300\uc758 2024 \uacc4\ud68d","date":"2024-02-29","coverUrl":null,"html":"<h2 data-notion-block-id=\\"e0624346-d2aa-40ff-a0cc-2e5ad7fb5c19\\" id=\\"e0624346-d2aa-40ff-a0cc-2e5ad7fb5c19\\">React \ud300\uc758 2024 \uacc4\ud68d</h2><a href=\\"https://react.dev/blog/2024/02/15/react-labs-what-we-have-been-working-on-february-2024\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react.dev/blog/2024/02/15/react-labs-what-we-have-been-working-on-february-2024</a><p data-notion-block-id=\\"26808dd7-54d2-4bb3-a778-3f9bb01ed942\\"><b>\uc2ec\uc724\uc12d</b>: React 19 \ubc84\uc804\uc758 \ucd9c\uc2dc \uc608\uace0\uc640 \ud568\uaed8 \ubca0\uc77c\uc5d0 \uc2f8\uc5ec\uc788\ub358 React Compiler, \uadf8 \uc678 \ub2e4\ub978 \uae30\ub2a5\uc744 \ucd9c\uc2dc\ud558\ub294\ub370\uc5d0 React\ud300\uc774 \uc9d1\uc911\ud558\uace0 \uc788\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. React Compiler\uac00 \uc774\uc804 RSC\uc640 \ub2e4\ub974\uac8c \uc548\uc815\uc801\uc73c\ub85c \ucda9\ubd84\ud55c \uc131\ub2a5(\ub80c\ub354\ub9c1 \ud639\uc740 \ucef4\ud30c\uc77c)\uc744 \ub0b4\ub294\uc9c0\uac00 \uc8fc\uc694 \uc7c1\uc810\uc774 \ub420 \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"512e0246-de02-488c-bf82-558547a5a65b\\"><b>\uae40\ub300\uad00</b>: React Compiler \uac1c\uc120\uc744 \ud1b5\ud574 \uba54\ubaa8\uc774\uc81c\uc774\uc158\uacfc \uac19\uc740 \uae30\ub2a5 \ucd5c\uc801\ud654\ub4e4\uc5d0 \ub300\ud55c \ubb38\uc81c\ub97c \ud574\uacb0\ud574\uc900\ub2e4\ub294 \ub0b4\uc6a9\uc740 \ub9e4\uc6b0 \ud765\ubbf8\ub86d\uc9c0\ub9cc, React \ub80c\ub354\ub9c1\uc744 \uc5b4\ub514\uae4c\uc9c0 \ucef4\ud30c\uc77c\ub7ec\uac00 \ud574\uc8fc\uace0 \uc5b4\ub514\ubd80\ud130 \uac1c\ubc1c\uc790\uac00 \ucd5c\uc801\ud654\ub97c \ud558\ub294\uac8c \uc633\uc744\uc9c0 \uad81\uae08\ud569\ub2c8\ub2e4. \ub610\ud55c \uae00\uc5d0\uc11c \ub9ac\uc561\ud2b8\uac00 RSC\ub97c \uc900\ube44\ud558\uba74\uc11c \uba54\ud0c0 \ubb38\uc11c\ub97c \ucd5c\uc801\ud654\ud55c\ub2e4\ub294 \ubd80\ubd84\uc740 \ub9e4\uc6b0 \ud765\ubbf8\ub86d\uae34 \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5e6449ed-4ac4-4dd8-bff6-7600c9059f75\\" id=\\"5e6449ed-4ac4-4dd8-bff6-7600c9059f75\\">LocalStorage\ub294 \uc5b8\uc81c \uc368\uc57c \ud558\ub294\uac00</h2><a href=\\"https://rxdb.info/articles/localstorage.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rxdb.info/articles/localstorage.html</a><p data-notion-block-id=\\"0b266d89-9db3-4644-90a9-6000b772aef8\\"><b>\uc2ec\uc724\uc12d</b>: \ube0c\ub77c\uc6b0\uc800\uc758 \uc0c1\ud0dc\ub97c \uc800\uc7a5\ud558\uae30 \uc704\ud574 Web Storage\ub97c \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc774 \ub54c localStorage\uc758 \ud2b9\uc131\uacfc \uc5b8\uc81c \uc368\uc57c \ud558\ub294\uc9c0\ub97c \ub9d0\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uac1c\uc778\uc801\uc73c\ub85c \uc778\uc99d, \uc778\uac00\ud560 \uacbd\uc6b0 \uc5b4\ub5a4 Web Storage\ub97c \uc368\uc57c \ud558\ub294\uc9c0 \uc0dd\uac01\ud574\ubcf4\uace0, React\uc5d0\uc11c localStorage\ub97c \uc0ac\uc6a9\ud558\uae30 \uc704\ud55c <a href=\\"https://thisweekinreact.com/articles/useSyncExternalStore-the-underrated-react-api\\"><code>useSyncExternalStore</code></a><a href=\\"https://thisweekinreact.com/articles/useSyncExternalStore-the-underrated-react-api\\">\uc758 \ud65c\uc6a9\ubc95</a>\ub3c4 \ud655\uc778\ud574\ubcf4\uc138\uc694.</p><p data-notion-block-id=\\"6b1e35b1-5d67-400b-959e-439fe107bea2\\"><b>\uae40\ub300\uad00</b>: \ub85c\uceec \uc2a4\ud1a0\ub9ac\uc9c0\ub97c \uc0dd\uac01\ud558\uba74 \uacfc\uac70 JWT Token \uc800\uc7a5\uacfc \uad00\ub828\ud574\uc11c \ucfe0\ud0a4\ub0d0 \ub85c\uceec\uc2a4\ud1a0\ub9ac\uc9c0\ub0d0 \uc815\ub9d0 \ub9ce\uc740 \ud1a0\ub860\uc744 \ud588\uc5c8\uc2b5\ub2c8\ub2e4. \uacb0\uad6d\uc740 \uc6f9\uc758 \ube44\uc5f0\uacb0\uc131\uc801\uc778 \ud2b9\uc9d5\uc744 \ubcf4\uc644\ud558\uae30 \uc704\ud55c \uc5ec\ub7ec \uc2a4\ud1a0\ub9ac\uc9c0\uc758 \ube44\uad50\ub3c4 \uc124\uba85\ud558\ub2c8 \uc798 \uc77d\uc5b4\ubcf4\uc2dc\uace0 \ubcf8\uc778\uc758 \ud658\uacbd\uc5d0\uc11c \ub9de\uac8c \uc0ac\uc6a9\ud558\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"fce4f296-01aa-4af3-8c6b-015e5363f1fb\\" id=\\"fce4f296-01aa-4af3-8c6b-015e5363f1fb\\">Favicon \uac00\uc774\ub4dc</h2><a href=\\"https://evilmartians.com/chronicles/how-to-favicon-in-2021-six-files-that-fit-most-needs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://evilmartians.com/chronicles/how-to-favicon-in-2021-six-files-that-fit-most-needs</a><p data-notion-block-id=\\"ed243f6e-14a8-4b7c-907a-4ec3561716d1\\"><b>\uc2ec\uc724\uc12d</b>: \uad6c\uae00\uc5d0 \uac80\uc0c9\ud558\ub294 Favicon \uc0dd\uc131\uae30\ub97c \ud1b5\ud574 Favicon\uc744 \uc0dd\uc131\ud558\uba74 \uc218\ub9ce\uc740 \ud30c\uc77c\uc774 \uc0dd\uc131\ub429\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc0dd\uc131\ub418\ub294 \ud30c\uc77c\uc758 \ub9ce\uc740 \ubd80\ubd84\uc774 \ud544\uc694 \uc5c6\uace0 \uadf8 \uc774\uc720\ub97c \uc124\uba85\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f1e1bd34-49ca-4fbb-b0a9-f4366c3c88df\\" id=\\"f1e1bd34-49ca-4fbb-b0a9-f4366c3c88df\\">Element\ub97c \uac00\uc6b4\ub370 \uc815\ub82c\ud558\uae30</h2><a href=\\"https://www.joshwcomeau.com/css/center-a-div/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/css/center-a-div/</a><p data-notion-block-id=\\"a03fd89d-1332-4158-8f2b-c4ff011c8e51\\"><b>\uc2ec\uc724\uc12d</b>: CSS\uc758 \ub2e4\uc591\ud55c \uae30\ub2a5\uc744 \ud1b5\ud574 HTML \uc694\uc18c\ub97c \uac00\uc6b4\ub370 \uc815\ub82c\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4. CSS\uc758 \ub2e4\uc591\ud55c \uae30\ub2a5\uc744 \uc544\ub294 \uac83\ub3c4 \uc88b\uc9c0\ub9cc \ube0c\ub77c\uc6b0\uc800\uac00 \uc9c0\uc6d0\ud558\uc9c0 \uc54a\uc744 \uac00\ub2a5\uc131\ub3c4 \uc788\uc73c\ub2c8 \ub2e4\uc591\ud55c \ud234(ex. browserlist\u2026)\ub97c \ud1b5\ud574 \ud638\ud658\uc131\uc744 \uc9c0\ud0a4\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"471383cb-e75b-46a6-b5db-2f11dcfca677\\" id=\\"471383cb-e75b-46a6-b5db-2f11dcfca677\\">React Native\uc5d0\uc11c DOM API\ub97c \uc0ac\uc6a9\ud55c\ub2e4\uba74</h2><a href=\\"https://github.com/facebook/react-strict-dom\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/facebook/react-strict-dom</a><p data-notion-block-id=\\"dd599f9a-88c4-4b1a-9887-902b959e125f\\">\uc6f9 \uac1c\ubc1c\uc790\uc758 React Native \uccab\ubc88\uc9f8 \uc7a5\ubcbd\uc740 DOM\uacfc CSS\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \uc774 \uc7a5\ubcbd\uc744 \ud5c8\ubb3c\uae30 \uc704\ud574 React \ud300\uc740 React Native \uac1c\ubc1c\uc744 React(DOM) \uac1c\ubc1c\ud558\ub294 \uac83\ucc98\ub7fc \uac1c\ubc1c\ud560 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4dc\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac \uac1c\ubc1c\uc5d0 \ucc29\uc218\ud588\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5e6b18a8-b9e0-40e7-9d7e-3e77b6d9f102\\" id=\\"5e6b18a8-b9e0-40e7-9d7e-3e77b6d9f102\\">UI\ub294 \uc0c1\ud0dc\uc758 \ud568\uc218\ub2e4.</h2><a href=\\"https://daverupert.com/2024/02/ui-states/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://daverupert.com/2024/02/ui-states/</a><p data-notion-block-id=\\"26caccd2-8059-4b1b-a1af-797f7f8343e4\\">UI\uc758 \uc0c1\ud0dc\ub97c \ud55c \uacf3\uc5d0\uc11c \uad00\ub9ac\ud558\ub824\uace0 \ud558\ub294 \uc2dc\ub3c4\ub294 \ub9ce\uc9c0\ub9cc Web API, \uc11c\ubc84\uc758 \uc0c1\ud0dc\uc640 \ub370\uc774\ud130, \ube0c\ub77c\uc6b0\uc800\uc758 \uc0c1\ud0dc\ub97c \ud55c \uacf3\uc5d0\uc11c \ubaa8\ub450 \uad00\ub9ac\ud558\uae30\ub294 \uc27d\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \ub2e8\uc21c\ud788 \uc0c1\ud0dc\ub294 \uc140 \uc218 \uc5c6\uc774 \ub9ce\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"6ce794ee-ad26-4f80-be7d-25b0870225fa\\" id=\\"6ce794ee-ad26-4f80-be7d-25b0870225fa\\">SVG \ud29c\ud1a0\ub9ac\uc5bc</h2><a href=\\"https://fffuel.co/svg-spinner/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fffuel.co/svg-spinner/</a><p data-notion-block-id=\\"4faafb28-83dd-4d7e-8d8d-27de9692c34f\\">svg \ub85c\ub529 \uc2a4\ud53c\ub108\ub97c \ub9cc\ub4e4\uc5b4 \uac00\uba70 SVG\uc5d0 \ub300\ud55c \uc18d\uc131\uc744 \uc548\ub0b4\ud569\ub2c8\ub2e4.</p>"}')}}]);